<script setup lang="ts">
// 产出与审核 tab：低置信全量 + 高置信抽检的标注审核队列。
// 保留键盘流（A 通过 / E 校正 / X 驳回 / G 黄金集 / S 稍后看 / ↑↓ 切换）；
// 卡片内嵌题面折叠预览（后端已带截断题面），动作按钮写明后果。
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import { GetEnrichReviewList, PostEnrichGoldenSet, PostEnrichReviewSet } from "@/apis/problem-enrichment";
import { reviewStatusText, taskTypeText, visibilityText } from "./enrich-common";
import type { EnrichActions } from "./enrich-common";
import AnnotationCard from "./AnnotationCard.vue";
import type { EnrichReviewItem } from "@/types/problem-enrichment";

const props = defineProps<{
  dataVersion: number;
  actions: EnrichActions;
}>();

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;

const reviewList = ref<EnrichReviewItem[]>([]);
const reviewTotal = ref(0);
const reviewPage = ref(1);
const reviewLoading = ref(false);
const reviewCursor = ref(0);
const reviewSubmitting = ref(false);
const rawDialogVisible = ref(false);
const rawDialogContent = ref<EnrichReviewItem | null>(null);

// 驳回理由对话框
const rejectDialogVisible = ref(false);
const rejectNote = ref("");
const rejectTargetId = ref(0);

// 每张卡片的题面展开状态
const statementOpen = ref<Record<number, boolean>>({});

const currentReview = computed(() => reviewList.value[reviewCursor.value] ?? null);

const fetchReviewList = async () => {
  reviewLoading.value = true;
  try {
    const res = await GetEnrichReviewList(reviewPage.value, 20);
    if (res.code === 0) {
      reviewList.value = res.data?.list ?? [];
      reviewTotal.value = res.data?.total ?? 0;
      reviewCursor.value = 0;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载审核队列失败");
  } finally {
    reviewLoading.value = false;
  }
};

const onReviewPageChange = async (info: { current: number }) => {
  reviewPage.value = info.current;
  await fetchReviewList();
};

const prettyJSON = (obj: unknown): string => {
  try {
    return JSON.stringify(obj, null, 2);
  } catch {
    return String(obj);
  }
};

// 从待审队列移除一条（审核动作完成后）
const removeReviewItem = (id: number) => {
  const idx = reviewList.value.findIndex((x) => x.id === id);
  if (idx >= 0) {
    reviewList.value.splice(idx, 1);
    reviewTotal.value -= 1;
    if (reviewCursor.value >= reviewList.value.length && reviewCursor.value > 0) {
      reviewCursor.value -= 1;
    }
  }
};

// 直接通过（不修改，公开标注即刻生效）
const reviewApprove = async (item: EnrichReviewItem) => {
  if (reviewSubmitting.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichReviewSet(item.id, "approved");
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已通过，该标注公开生效");
      removeReviewItem(item.id);
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

const openRejectDialog = (item: EnrichReviewItem) => {
  rejectTargetId.value = item.id;
  rejectNote.value = "";
  rejectDialogVisible.value = true;
};

const confirmReject = async () => {
  if (!rejectTargetId.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichReviewSet(rejectTargetId.value, "rejected", rejectNote.value.trim());
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已驳回，该标注不生效，可重判重新生成");
      rejectDialogVisible.value = false;
      removeReviewItem(rejectTargetId.value);
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

const toggleGolden = async (item: EnrichReviewItem) => {
  if (reviewSubmitting.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichGoldenSet(item.id, !item.golden);
    if (res.code === 0) {
      item.golden = !item.golden;
      ShowTextTipsInfo(globalProperties, item.golden ? "已冻结为黄金集基准" : "已解除黄金集");
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

// 稍后看：本地把当前项移到队尾（不落库，刷新即恢复）
const skipCurrent = () => {
  const item = currentReview.value;
  if (!item || reviewList.value.length <= 1) {
    return;
  }
  reviewList.value.splice(reviewCursor.value, 1);
  reviewList.value.push(item);
  reviewCursor.value = Math.min(reviewCursor.value, reviewList.value.length - 1);
  ShowTextTipsInfo(globalProperties, "已移到最后（仅本地，刷新后恢复）");
};

const openRawDialog = (item: EnrichReviewItem) => {
  rawDialogContent.value = item;
  rawDialogVisible.value = true;
};

// 校正：打开人工标注抽屉；保存后推进到下一条待审（注册回调）
const openCuratorForReview = (item: EnrichReviewItem) => {
  reviewCursor.value = reviewList.value.indexOf(item);
  props.actions.openCurator(
    item.problem_id,
    item.task_type,
    true,
    ({ taskType }) => {
      // 保存后：按保存的 problem + 类型移除该待审项，并自动打开下一条
      const idx = reviewList.value.findIndex(
        (x) => x.problem_id === item.problem_id && x.task_type === taskType
      );
      if (idx >= 0) {
        reviewList.value.splice(idx, 1);
        reviewTotal.value -= 1;
      }
      const next = reviewList.value[reviewCursor.value] ?? reviewList.value[reviewCursor.value - 1] ?? null;
      if (next) {
        openCuratorForReview(next);
      } else {
        props.actions.refreshAll();
      }
    },
    ({ annotationId }) => {
      const idx = reviewList.value.findIndex((x) => x.id === annotationId);
      if (idx >= 0) {
        reviewList.value.splice(idx, 1);
        reviewTotal.value -= 1;
      }
      const next = reviewList.value[reviewCursor.value] ?? reviewList.value[reviewCursor.value - 1] ?? null;
      if (next) {
        openCuratorForReview(next);
      }
    }
  );
};

// 键盘流：A 通过 · E 校正 · X 驳回 · G 黄金集 · S 稍后看 · ↑↓ 切换
const onReviewKeydown = (e: KeyboardEvent) => {
  if (rawDialogVisible.value || rejectDialogVisible.value) {
    return;
  }
  const target = e.target as HTMLElement | null;
  if (target && ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName)) {
    return;
  }
  const item = currentReview.value;
  if (!item) {
    return;
  }
  if (e.key === "a" || e.key === "A") {
    e.preventDefault();
    reviewApprove(item);
  } else if (e.key === "x" || e.key === "X") {
    e.preventDefault();
    reviewCursor.value = reviewList.value.indexOf(item);
    openRejectDialog(item);
  } else if (e.key === "e" || e.key === "E") {
    e.preventDefault();
    openCuratorForReview(item);
  } else if (e.key === "g" || e.key === "G") {
    e.preventDefault();
    toggleGolden(item);
  } else if (e.key === "s" || e.key === "S") {
    e.preventDefault();
    skipCurrent();
  } else if (e.key === "ArrowDown") {
    e.preventDefault();
    if (reviewCursor.value < reviewList.value.length - 1) {
      reviewCursor.value += 1;
    }
  } else if (e.key === "ArrowUp") {
    e.preventDefault();
    if (reviewCursor.value > 0) {
      reviewCursor.value -= 1;
    }
  }
};

// 键盘流只在审核 tab 激活时生效：keydown 监听随组件挂载/卸载自动增删
watch(
  () => props.dataVersion,
  () => {
    // 外部动作（如详情抽屉里重判）后刷新队列
    fetchReviewList();
  }
);

onMounted(() => {
  fetchReviewList();
  window.addEventListener("keydown", onReviewKeydown);
});
onBeforeUnmount(() => {
  window.removeEventListener("keydown", onReviewKeydown);
});
</script>

<template>
  <div class="enrich-review">
    <div class="enrich-toolbar">
      <t-alert
        theme="info"
        :message="`键盘流：A 直接通过（公开生效）· E 人工校正 · X 驳回（不生效，可重判）· G 黄金集 · S 稍后看 · ↑↓ 切换（共 ${reviewTotal} 条待审）`"
      />
      <t-button variant="outline" :loading="reviewLoading" @click="fetchReviewList">刷新</t-button>
    </div>

    <div v-if="reviewList.length === 0 && !reviewLoading" class="enrich-empty">暂无待审核标注</div>

    <div
      v-for="(item, index) in reviewList"
      :key="item.id"
      class="review-card"
      :class="{ 'review-card-active': index === reviewCursor }"
      @click="reviewCursor = index"
    >
      <div class="review-card-head">
        <t-space size="small" break-line>
          <t-tag theme="primary" variant="light">{{ taskTypeText[item.task_type] || item.task_type }}</t-tag>
          <t-tag variant="outline">{{ visibilityText[item.visibility] || item.visibility }}</t-tag>
          <t-tag v-if="item.source === 'human'" theme="default" variant="dark">人工</t-tag>
          <t-tag v-if="item.golden" theme="warning" variant="dark">黄金集</t-tag>
          <span class="review-title">{{ item.problem_title || `题目 #${item.problem_id}` }}</span>
        </t-space>
        <t-space size="small">
          <span class="review-meta">置信度 {{ (item.confidence * 100).toFixed(0) }}%</span>
          <span class="review-meta">{{ item.model }}</span>
          <t-button size="small" variant="text" @click.stop="openRawDialog(item)">原始响应</t-button>
          <t-button size="small" variant="text" @click.stop="props.actions.openDetail(item.problem_id, item.problem_key)">
            全部产出
          </t-button>
        </t-space>
      </div>

      <!-- 题面折叠预览：判断摘要剧透/难度合理性不再需要跳转 -->
      <div v-if="item.problem_statement" class="review-statement">
        <div class="review-statement-head">
          <t-button
            size="small"
            variant="text"
            theme="primary"
            @click.stop="statementOpen[item.id] = !statementOpen[item.id]"
          >
            {{ statementOpen[item.id] ? "收起题面" : "展开题面预览" }}
          </t-button>
        </div>
        <div v-if="statementOpen[item.id]" class="review-statement-body">
          {{ item.problem_statement }}
        </div>
      </div>

      <!-- 分型只读预览 -->
      <div class="review-preview">
        <AnnotationCard
          :task-type="item.task_type"
          :payload="item.payload ?? {}"
          :meta="{
            visibility: item.visibility,
            source: item.source,
            golden: item.golden,
            review_status: item.review_status,
            confidence: item.confidence,
            model: item.model,
          }"
        />
      </div>

      <div class="review-card-foot">
        <t-space size="small" break-line>
          <t-button
            size="small"
            theme="success"
            :loading="reviewSubmitting && index === reviewCursor"
            @click.stop="reviewApprove(item)"
          >
            通过 (A) · 公开生效
          </t-button>
          <t-button size="small" theme="primary" @click.stop="openCuratorForReview(item)">
            人工校正 (E)
          </t-button>
          <t-button size="small" theme="danger" variant="outline" @click.stop="openRejectDialog(item)">
            驳回 (X) · 不生效
          </t-button>
          <t-button size="small" variant="outline" @click.stop="toggleGolden(item)">
            {{ item.golden ? "解除黄金集 (G)" : "冻结黄金集 (G)" }}
          </t-button>
          <t-button size="small" variant="text" @click.stop="skipCurrent">稍后看 (S)</t-button>
          <span class="review-meta">{{ reviewStatusText[item.review_status] }}</span>
        </t-space>
      </div>
    </div>

    <div v-if="reviewTotal > 20" class="enrich-pagination">
      <t-pagination :current="reviewPage" :pageSize="20" :total="reviewTotal" @change="onReviewPageChange" />
    </div>

    <!-- 驳回理由对话框 -->
    <t-dialog
      v-model:visible="rejectDialogVisible"
      header="驳回标注"
      :confirm-loading="reviewSubmitting"
      @confirm="confirmReject"
    >
      <p>驳回后该标注不生效，会留在历史记录中，可对题目重判重新生成。请填写驳回理由（可选，留痕给后续优化 prompt）：</p>
      <t-textarea v-model="rejectNote" :autosize="{ minRows: 3 }" placeholder="驳回理由（可选）" />
    </t-dialog>

    <!-- 原始响应对话框 -->
    <t-dialog v-model:visible="rawDialogVisible" header="模型原始响应" :footer="false" width="720px" :destroy-on-close="true">
      <template v-if="rawDialogContent">
        <t-descriptions
          :column="1"
          bordered
          :data="[
            { label: '题目', value: rawDialogContent.problem_title || `#${rawDialogContent.problem_id}` },
            { label: '模型', value: rawDialogContent.model },
            { label: 'Prompt 版本', value: rawDialogContent.prompt_ver || '—' },
            { label: 'Schema 版本', value: rawDialogContent.schema_ver || '—' },
          ]"
        />
        <h4>结构化 payload</h4>
        <pre class="review-payload">{{ prettyJSON(rawDialogContent.payload) }}</pre>
        <h4>raw_response</h4>
        <pre class="review-raw">{{ rawDialogContent.raw_response || "（未留存）" }}</pre>
      </template>
    </t-dialog>
  </div>
</template>

