<script setup lang="ts">
// 题目列表 tab：状态机全量列表。行内直接展示流水线进度与公开产出（难度/标签/摘要），
// 「查看产出」打开只读详情抽屉；10 秒轮询（可关），页面不可见时暂停。
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import { GetEnrichStateList, PostEnrichRejudge } from "@/apis/problem-enrichment";
import { stateStatusText, stateStatusTheme, gradeName, fmtTime, fmtAgo, stageText } from "./enrich-common";
import EnrichPipelineSteps from "./EnrichPipelineSteps.vue";
import type { EnrichStateItem, EnrichStateStatus } from "@/types/problem-enrichment";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { handleGotoProblem } from "@/util/router";

const props = defineProps<{
  dataVersion: number; // 父组件在外部动作（重判/人工定稿）后递增，触发本组件刷新
  filterRequest?: { statuses: number[]; seq: number } | null; // 总览状态卡点击下钻：切换筛选
}>();

const emit = defineEmits<{
  (e: "open-detail", problemId: number, problemKey?: string): void;
  (e: "open-curator", problemId: number, taskType: string): void;
}>();

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;
const { isMobile } = useBreakpoint();

const pageSize = isMobile.value ? 20 : 50;

const stateList = ref<EnrichStateItem[]>([]);
const stateTotal = ref(0);
const statePage = ref(1);
const stateFilter = ref<number[]>([]);
const stateLoading = ref(false);
const autoRefresh = ref(true);

const stateStatusOptions = [
  { label: "未处理", value: 0 },
  { label: "排队", value: 1 },
  { label: "处理中", value: 2 },
  { label: "成功", value: 3 },
  { label: "失败", value: 4 },
];

const statePagination = computed(() => ({
  current: statePage.value,
  pageSize,
  total: stateTotal.value,
  defaultCurrent: 1,
  defaultPageSize: pageSize,
}));

const difficultyTheme: Record<number, string> = {
  1: "default",
  2: "success",
  3: "warning",
  4: "danger",
  5: "error",
};

const stateColumns = [
  { colKey: "problem_id", title: "题目", minWidth: 170 },
  { colKey: "status", title: "状态", width: 84 },
  { colKey: "pipeline", title: "流水线", minWidth: 170 },
  { colKey: "output", title: "公开产出", minWidth: 220 },
  { colKey: "attempt", title: "尝试", width: 56 },
  { colKey: "modify_time", title: "更新", width: 150 },
  { colKey: "operation", title: "操作", width: 230, fixed: "right" as const },
];

const fetchStateList = async () => {
  stateLoading.value = true;
  try {
    const res = await GetEnrichStateList(
      stateFilter.value.length > 0 ? (stateFilter.value as EnrichStateStatus[]) : null,
      statePage.value,
      pageSize
    );
    if (res.code === 0) {
      stateList.value = res.data?.list ?? [];
      stateTotal.value = res.data?.total ?? 0;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载状态列表失败");
  } finally {
    stateLoading.value = false;
  }
};

const onStatePageChange = (info: { current: number }) => {
  statePage.value = info.current;
  fetchStateList();
};

const onStateFilterChange = () => {
  statePage.value = 1;
  fetchStateList();
};

// 手动重判（强制，可解救处理中卡死题）
const handleRejudge = async (row: EnrichStateItem) => {
  try {
    const res = await PostEnrichRejudge(row.problem_id);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已强制重新入队，judge 将重新处理");
      await fetchStateList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// 10s 轮询（可关），页面不可见时暂停
let timer: ReturnType<typeof setInterval> | null = null;
const startPolling = () => {
  stopPolling();
  if (!autoRefresh.value) {
    return;
  }
  timer = setInterval(() => {
    if (document.visibilityState === "visible") {
      fetchStateList();
    }
  }, 10000);
};
const stopPolling = () => {
  if (timer) {
    clearInterval(timer);
    timer = null;
  }
};
const onVisibility = () => {
  if (document.visibilityState === "visible") {
    fetchStateList();
  }
};
watch(autoRefresh, startPolling);
watch(() => props.dataVersion, fetchStateList);
// 总览下钻：应用筛选请求（seq 变化即生效，切回 tab 重挂载时也会在 onMounted 应用一次）
watch(
  () => props.filterRequest?.seq,
  (seq) => {
    if (seq != null && props.filterRequest) {
      stateFilter.value = [...props.filterRequest.statuses];
      statePage.value = 1;
      fetchStateList();
    }
  }
);

onMounted(() => {
  if (props.filterRequest) {
    stateFilter.value = [...props.filterRequest.statuses];
  }
  fetchStateList();
  startPolling();
  document.addEventListener("visibilitychange", onVisibility);
});
onBeforeUnmount(() => {
  stopPolling();
  document.removeEventListener("visibilitychange", onVisibility);
});
</script>

<template>
  <div class="enrich-state">
    <div class="enrich-toolbar">
      <t-select
        v-model="stateFilter"
        :options="stateStatusOptions"
        multiple
        clearable
        placeholder="按状态筛选"
        style="min-width: 220px"
        @change="onStateFilterChange"
      />
      <t-switch v-model="autoRefresh" size="small" />
      <span class="toolbar-hint">自动刷新 10s</span>
      <t-button variant="outline" @click="fetchStateList">刷新</t-button>
    </div>

    <div class="enrich-table-wrap">
      <t-table
        :data="stateList"
        :columns="stateColumns"
        :loading="stateLoading"
        row-key="problem_id"
        table-layout="auto"
        :pagination="statePagination"
        @page-change="onStatePageChange"
      >
        <template #problem_id="{ row }">
          <t-button variant="text" @click="handleGotoProblem(row.problem_key)">
            {{ row.problem_key || row.problem_id }}
          </t-button>
          <div class="enrich-problem-title">{{ row.problem_title }}</div>
        </template>
        <template #status="{ row }">
          <t-tag :theme="stateStatusTheme[row.status]" variant="light">
            {{ stateStatusText[row.status] }}
          </t-tag>
          <!-- 处理中/排队：显示当前阶段与已耗时，避免「卡死」错觉 -->
          <div v-if="row.status === 2 || row.status === 1" class="state-running-meta">
            <span v-if="row.stage && row.status === 2" class="state-running-stage">
              {{ stageText[row.stage] || row.stage }}
            </span>
            <span class="state-running-ago">{{ fmtAgo(row.modify_time) }}</span>
          </div>
        </template>
        <template #pipeline="{ row }">
          <EnrichPipelineSteps :steps="row.steps ?? []" size="sm" />
        </template>
        <template #output="{ row }">
          <div class="state-output">
            <div class="state-output-line">
              <t-tag
                v-if="row.difficulty > 0"
                size="small"
                :theme="difficultyTheme[row.difficulty]"
                variant="light"
              >
                {{ row.difficulty_name || gradeName(row.difficulty) }}
              </t-tag>
              <span v-else class="state-output-empty">未标注难度</span>
              <t-tag
                v-for="t in row.tag_names ?? []"
                :key="t"
                size="small"
                variant="outline"
                class="state-tag-chip"
              >
                {{ t }}
              </t-tag>
            </div>
            <div v-if="row.summary_line" class="state-output-summary" :title="row.summary_line">
              {{ row.summary_line }}
            </div>
            <div v-else-if="row.message" class="state-output-fail" :title="row.message">
              {{ row.message }}
            </div>
          </div>
        </template>
        <template #attempt="{ row }">{{ row.attempt }}</template>
        <template #modify_time="{ row }">{{ fmtTime(row.modify_time) }}</template>
        <template #operation="{ row }">
          <t-space size="small" break-line>
            <t-button size="small" theme="primary" variant="text" @click="emit('open-detail', row.problem_id, row.problem_key)">
              查看产出
            </t-button>
            <t-popconfirm
              :content="row.status === 2 ? '该题正被 worker 认领（可能卡死），强制重判会夺回并重新处理，确定？' : '强制重新入队并重新跑完整流水线，确定？'"
              @confirm="handleRejudge(row)"
            >
              <t-button size="small" variant="text">重判</t-button>
            </t-popconfirm>
            <t-button
              size="small"
              variant="text"
              theme="success"
              @click="emit('open-curator', row.problem_id, 'summary')"
            >
              人工标注
            </t-button>
          </t-space>
        </template>
      </t-table>
    </div>
  </div>
</template>

